    if(c.effect_code==='destroy_spell_target'){const s=side(foe);return [...s.spells.map((slot,index)=>({slot,index,name:foe,type:'spell'})),{slot:s.field,index:-1,name:foe,type:'field'}].filter(e=>e.slot);}
